<?php
function reversal_source($type,$id){
 $pdo=db();$plan=['type'=>$type,'id'=>$id,'inflows'=>[],'outflows'=>[],'non_sellable'=>[],'returns'=>[],'platforms'=>[],'nonsellable_outflows'=>[],'release_links'=>[],'transfers'=>[]];
 if($type==='Repackaging Batch'){$plan=repack_reversal_plan($id,$plan);}
 elseif($type==='Packaging Completion'){$plan=packaging_reversal_plan($id,$plan);}
 elseif($type==='Inflow'){$q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=?');$q->execute([$id]);$b=$q->fetch();if(!$b||$b['status']!=='Confirmed')throw new Exception('Select a confirmed inflow batch.');if(!in_array($b['batch_type'],['Manual','Excel Upload','Receipt PDF'],true))throw new Exception('Reverse order returns using their Return record.');$q=$pdo->prepare('SELECT * FROM inflows WHERE batch_id=? ORDER BY id');$q->execute([$id]);$plan['inflows']=$q->fetchAll();$meta=json_decode($b['result_json'],true)?:[];if(isset($meta['non_sellable_id'])){$q=$pdo->prepare('SELECT * FROM non_sellable WHERE id=?');$q->execute([$meta['non_sellable_id']]);$plan['non_sellable']=$q->fetchAll();}
 $allocation=$meta['incoming_allocation']['lines']??[];if(!$allocation&&$plan['inflows'])throw new Exception('This legacy inflow has no recorded platform allocation. Review its allocation evidence before a correction; the system cannot guess the original platform movement.');foreach($allocation as $pid=>$line)foreach(['Shopee','Lazada','TikTok'] as $pl)if((int)$line[$pl])$plan['platforms'][]=['pid'=>(int)$pid,'platform'=>$pl,'delta'=>-(int)$line[$pl]];$plan['reference']=$b['batch_ref'];
 }elseif(in_array($type,['Outflow','Manual Outflow'],true)){$sql=$type==='Outflow'?'SELECT * FROM outflows WHERE import_batch_id=? ORDER BY id':'SELECT * FROM outflows WHERE id=?';$q=$pdo->prepare($sql);$q->execute([$id]);$plan['outflows']=$q->fetchAll();if(!$plan['outflows'])throw new Exception('Posted outflow not found.');foreach($plan['outflows'] as $row){if($row['reversed_by_request']!==null||in_array($row['type'],['Reversal','Borrowed Issue','Inventory Count Adjustment'],true))throw new Exception('This movement is reversed or must be corrected through its linked workflow.');$pl=in_array($row['platform'],['Shopee','Lazada','TikTok'],true)?$row['platform']:trim(str_replace('Stock source: ','',$row['source_item']));stock_platform($pl);if($row['type']==='Order'&&order_return_balance($pl,$row['order_id'],$row['product_id'])['returned']>0)throw new Exception('This order has returns. Reverse the linked return first to avoid double-restoring stock.');$plan['platforms'][]=['pid'=>(int)$row['product_id'],'platform'=>$pl,'delta'=>(int)$row['qty']];}$plan['reference']=$type.' #'.$id;
 }elseif($type==='Return'){$b=return_batch($id);if($b['status']!=='Posted')throw new Exception('Select a posted return.');$q=$pdo->prepare('SELECT * FROM posted_returns WHERE batch_id=? AND reversed=0 ORDER BY id');$q->execute([$id]);$plan['returns']=$q->fetchAll();foreach($plan['returns'] as $r){if(warranty_used($r['id'])>0)throw new Exception('This return has posted warranty replacements. Reverse the linked replacements first.');if($r['inflow_id']){$q=$pdo->prepare('SELECT * FROM inflows WHERE id=?');$q->execute([$r['inflow_id']]);$plan['inflows'][]=$q->fetch();$plan['platforms'][]=['pid'=>(int)$r['product_id'],'platform'=>$r['platform'],'delta'=>-(int)$r['good_qty']];}if($r['non_sellable_id']){$q=$pdo->prepare('SELECT * FROM non_sellable WHERE id=?');$q->execute([$r['non_sellable_id']]);$plan['non_sellable'][]=$q->fetch();}}$plan['reference']=$b['batch_ref'];
 }elseif($type==='Non-Sellable'){$q=$pdo->prepare('SELECT * FROM non_sellable WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['reversed_by_request']!==null||in_array($r['origin'],['Order Return','Borrowed Return','Inventory Count','Reversal','Repackaging Batch'],true))throw new Exception('Use the linked return/count workflow for this movement.');$plan['non_sellable']=[$r];if($r['sellable_deducted'])$plan['platforms'][]=['pid'=>(int)$r['product_id'],'platform'=>stock_platform($r['platform']),'delta'=>(int)$r['qty']];$plan['reference']='NS-'.$id;
 }elseif($type==='Non-Sellable Release'){$q=$pdo->prepare('SELECT * FROM nonsellable_outflows WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['reversed_by_request']!==null||in_array($r['type'],['Reversal','Inventory Count Adjustment','Ready for Sale','Repackaging Reclassification'],true))throw new Exception('Release unavailable or linked to a count.');$q=$pdo->prepare('SELECT * FROM nonsellable_release_links WHERE release_id=?');$q->execute([$id]);$links=$q->fetchAll();if(!$links)throw new Exception('Legacy release has no original Non-Sellable link; review its evidence first.');$plan['nonsellable_outflows']=[$r];$plan['release_links']=$links;$plan['reference']='NS-RELEASE-'.$id;
 }elseif($type==='Stock Transfer'){$q=$pdo->prepare('SELECT * FROM platform_transfers WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['reversed_by_request']!==null||str_starts_with($r['transfer_ref'],'REV-'))throw new Exception('Transfer already reversed or unavailable.');$plan['transfers']=[$r];$plan['platforms']=[['pid'=>(int)$r['product_id'],'platform'=>$r['from_platform'],'delta'=>(int)$r['qty']],['pid'=>(int)$r['product_id'],'platform'=>$r['to_platform'],'delta'=>-(int)$r['qty']]];$plan['reference']=$r['transfer_ref'];
 }elseif($type==='Inventory Count'){$q=$pdo->prepare("SELECT * FROM inventory_count_batches WHERE id=? AND status='Applied'");$q->execute([$id]);$b=$q->fetch();if(!$b)throw new Exception('Select an applied inventory count.');$plan['reference']=$b['batch_ref'];foreach(['inflows'=>'reference_no','outflows'=>'order_id','non_sellable'=>'order_id','nonsellable_outflows'=>'reference_no'] as $table=>$ref){$q=$pdo->prepare('SELECT * FROM '.$table.' WHERE '.$ref.'=? AND reversed_by_request IS NULL ORDER BY id');$q->execute([$b['batch_ref']]);$plan[$table]=$q->fetchAll();}$q=$pdo->prepare('SELECT product_id,platform,SUM(after_qty-before_qty) delta FROM stock_events WHERE reference_no=? GROUP BY product_id,platform');$q->execute([$b['batch_ref']]);foreach($q as $m)if($m['delta'])$plan['platforms'][]=['pid'=>(int)$m['product_id'],'platform'=>$m['platform'],'delta'=>-(int)$m['delta']];foreach($plan['nonsellable_outflows'] as $release){$q=$pdo->prepare('SELECT * FROM nonsellable_release_links WHERE release_id=?');$q->execute([$release['id']]);$plan['release_links']=array_merge($plan['release_links'],$q->fetchAll());}if(!$plan['platforms']&&($plan['inflows']||$plan['outflows']))throw new Exception('This legacy count has no original platform trail. Review allocation evidence before reversing.');
 }else throw new Exception('Unsupported reversal type.');
 if(function_exists('repack_ready')&&repack_ready()&&$type!=='Repackaging Batch')foreach($plan['non_sellable'] as $n){$q=db()->prepare("SELECT COUNT(*) FROM repackaging_batch_lines l JOIN repackaging_batches b ON b.id=l.batch_id WHERE (l.source_id=? OR l.target_id=?) AND b.status='Posted'");$q->execute([$n['id'],$n['id']]);if($q->fetchColumn())throw new Exception('This source belongs to a posted repackaging batch. Reverse that batch first.');}
 if(!in_array($type,['Repackaging Batch','Inventory Count'],true)&&!$plan['inflows']&&!$plan['outflows']&&!$plan['non_sellable']&&!$plan['nonsellable_outflows']&&!$plan['transfers'])throw new Exception('No posted movements to reverse.');$plan['signature']=hash('sha256',json_encode($plan));return $plan;
}
function reversal_request($type,$id,$reason){$reason=process_reason($reason);$plan=reversal_source($type,$id);$q=db()->prepare("SELECT COUNT(*) FROM transaction_reversals WHERE source_type=? AND source_id=? AND status IN ('Pending','Approved')");$q->execute([$type,$id]);if($q->fetchColumn())throw new Exception('A reversal is already pending or approved for this source.');db()->prepare('INSERT INTO transaction_reversals(source_type,source_id,reason,requested_by,result_json) VALUES(?,?,?,?,?)')->execute([$type,$id,$reason,current_user()['id'],json_encode($plan)]);$rid=(int)db()->lastInsertId();audit('Request transaction reversal','Reversal',(string)$rid,$plan['reference'].'; '.$reason);return $rid;}
function reversal_approve($id){if(current_user()['role']!=='Admin')throw new Exception('Administrator approval required.');return process_transaction(function()use($id){$q=db()->prepare('SELECT * FROM transaction_reversals WHERE id=? FOR UPDATE');$q->execute([$id]);$request=$q->fetch();if(!$request||$request['status']!=='Pending')throw new Exception('Reversal is no longer pending.');if($request['source_type']==='Inventory Count'&&(int)$request['requested_by']===current_user()['id'])throw new Exception('A different Admin must approve an inventory adjustment reversal.');$old=json_decode($request['result_json'],true);$plan=reversal_source($request['source_type'],$request['source_id']);if(!hash_equals($old['signature'],$plan['signature']))throw new Exception('Source transaction changed. Review it before approving.');$ids=[];foreach(['inflows','outflows','non_sellable','nonsellable_outflows','transfers'] as $kind)foreach($plan[$kind] as $r)$ids[]=(int)$r['product_id'];foreach($plan['platforms'] as $m)$ids[]=(int)$m['pid'];$ids=array_unique($ids);sort($ids,SORT_NUMERIC);foreach($ids as $pid){db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$pid]);check_platform_alignment($pid);}
 $damage=[];foreach($plan['non_sellable'] as $r){if(release_total($r['id'])>0)throw new Exception('Non-Sellable stock from this transaction was already released. Review the linked release first.');$damage[$r['product_id']]=($damage[$r['product_id']]??0)+(int)$r['qty'];}foreach($damage as $pid=>$qty)if(stock_row($pid)['nonsellable']<$qty)throw new Exception('Insufficient remaining Non-Sellable quantity to reverse.');$ref='REV-'.$id;$date=date('Y-m-d');$uid=current_user()['id'];$note=$plan['reference'].'; '.$request['reason'];
 foreach($plan['inflows'] as $r){db()->prepare('INSERT INTO inflows(txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$date,$ref,$plan['reference'],$r['source_platform'],$r['product_id'],-(int)$r['qty'],'pc',-(int)$r['qty'],'Reversal',$note,$uid]);db()->prepare('UPDATE inflows SET reversed_by_request=? WHERE id=?')->execute([$id,$r['id']]);}
 foreach($plan['outflows'] as $r){db()->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$date,$r['platform'],$ref,$r['product_id'],$r['source_item'],-(int)$r['qty'],'Reversal',$note,$uid]);db()->prepare('UPDATE outflows SET reversed_by_request=?,dedupe_key=NULL WHERE id=?')->execute([$id,$r['id']]);}
 foreach($plan['non_sellable'] as $r){db()->prepare('UPDATE non_sellable SET reversed_by_request=? WHERE id=?')->execute([$id,$r['id']]);db()->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$date,$r['platform'],$ref,$r['product_id'],-(int)$r['qty'],$r['condition_type'],'Reversal','Reversed','Reversal',(int)$r['sellable_deducted'],$note,$uid]);}
 foreach($plan['nonsellable_outflows'] as $r){db()->prepare('UPDATE nonsellable_outflows SET reversed_by_request=? WHERE id=?')->execute([$id,$r['id']]);db()->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$date,$r['product_id'],-(int)$r['qty'],'Reversal',$ref,$note,$uid]);$newRelease=(int)db()->lastInsertId();foreach($plan['release_links'] as $link)if((int)$link['release_id']===(int)$r['id'])db()->prepare('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)')->execute([$newRelease,$link['non_sellable_id'],-(int)$link['qty']]);}
 foreach($plan['transfers'] as $r){db()->prepare('UPDATE platform_transfers SET reversed_by_request=? WHERE id=?')->execute([$id,$r['id']]);db()->prepare('INSERT INTO platform_transfers(transfer_ref,txn_date,product_id,from_platform,to_platform,qty,reason,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$ref,$date,$r['product_id'],$r['to_platform'],$r['from_platform'],$r['qty'],$note,$uid]);}
 if($request['source_type']==='Repackaging Batch')db()->prepare("UPDATE repackaging_batches SET status='Reversed',reversed_by_request=? WHERE id=?")->execute([$id,$request['source_id']]);
 if($request['source_type']==='Packaging Completion'){db()->prepare('UPDATE packaging_completions SET reversed_by_request=? WHERE id=?')->execute([$id,$request['source_id']]);db()->prepare("UPDATE non_sellable SET packaging_state='For Inspection' WHERE id=?")->execute([$plan['completion']['source_id']]);}
 if($request['source_type']==='Inventory Count'){db()->prepare("UPDATE inventory_count_batches SET status='Reversed' WHERE id=?")->execute([$request['source_id']]);if(adjustments_ready())adjustment_event($request['source_id'],'Linked reversal',['reference'=>$ref,'request_id'=>$id,'reason'=>$request['reason']]);}
 foreach($plan['platforms'] as $move)change_platform_stock($move['platform'],$move['pid'],$move['delta'],$ref,$date);foreach($ids as $pid)check_platform_alignment($pid);
 if($request['source_type']==='Inflow'){db()->prepare("UPDATE inflow_batches SET status='Reversed' WHERE id=?")->execute([$request['source_id']]);db()->prepare('DELETE FROM inflow_receipt_claims WHERE batch_id=?')->execute([$request['source_id']]);}
 if($request['source_type']==='Outflow')db()->prepare("UPDATE import_batches SET status='Reversed' WHERE id=?")->execute([$request['source_id']]);
 if($request['source_type']==='Return'){db()->prepare('UPDATE posted_returns SET reversed=1 WHERE batch_id=?')->execute([$request['source_id']]);db()->prepare("UPDATE return_batches SET status='Reversed' WHERE id=?")->execute([$request['source_id']]);inflow_sync_return_history($request['source_id']);}
 db()->prepare("UPDATE transaction_reversals SET status='Approved',approved_by=?,approved_at=NOW() WHERE id=?")->execute([$uid,$id]);audit('Approve transaction reversal','Reversal',$ref,$note.'; original records preserved; inverse platform movements posted once.');return $ref;});}

function reversal_reject($id,$reason){if(current_user()['role']!=='Admin')throw new Exception('Administrator approval required.');$reason=process_reason($reason);$q=db()->prepare("UPDATE transaction_reversals SET status='Rejected',approved_by=?,approved_at=NOW() WHERE id=? AND status='Pending'");$q->execute([current_user()['id'],$id]);if(!$q->rowCount())throw new Exception('Request is no longer pending.');audit('Reject transaction reversal','Reversal','REV-'.$id,$reason);}
